/** Erweiterte Sätze laufen unter eigener ID, z.B. "s1-bwl~ext". */
export const extQuizId = (moduleId) => `${moduleId}${EXT_SUFFIX}`;
export const baseQuizId = (id) => (id.endsWith(EXT_SUFFIX) ? id.slice(0, -EXT_SUFFIX.length) : null);
